/*
 * Host tests for the signal generator's pure layer (src/dsp/siggen_wave.c):
 *   1. every 100-sample cycle equals stock V1.2.0's builder (0x08029E14),
 *      emulated in unicorn (fixtures/siggen_stock_waves.h, generated by
 *      scripts/gen_siggen_stock_waves.py);
 *   2. TMR7 DIV/PR give 100 updates per cycle, never a PR of 0, never a
 *      register overflow, and are never less accurate than stock's own
 *      formula at any integer frequency 1..50000 Hz;
 *   3. the DAC_CTRL composer leaves channel 1 (bits 15:0, the scope's
 *      CH1 offset DAC) bit-for-bit unchanged.
 *
 * Run: make test-siggen
 */

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "siggen_wave.h"
#include "fixtures/siggen_stock_waves.h"

static int failures = 0;
static int checks = 0;

#define CHECK(cond, ...) do {                                   \
    checks++;                                                   \
    if (!(cond)) {                                              \
        failures++;                                             \
        printf("  FAIL %s:%d: ", __FILE__, __LINE__);           \
        printf(__VA_ARGS__);                                    \
        printf("\n");                                           \
    }                                                           \
} while (0)

#define TMR7_CLK 240000000u   /* RESULTS.md S5: DIV 1199 / PR 1 -> 998 Hz at "1 kHz" */

static void test_stock_cycles(void)
{
    printf("[1] cycles vs emulated stock builder (%u cases)\n",
           (unsigned)SIGGEN_STOCK_CASE_COUNT);
    unsigned bad = 0;
    for (size_t c = 0; c < SIGGEN_STOCK_CASE_COUNT; c++) {
        const siggen_stock_case_t *k = &siggen_stock_cases[c];
        uint16_t out[SIGGEN_CYCLE_SAMPLES];
        siggen_wave_build(out, k->wave, k->amp, k->duty);
        for (unsigned i = 0; i < SIGGEN_CYCLE_SAMPLES; i++) {
            if (out[i] != k->code[i]) {
                if (bad < 8)
                    printf("  wave %u amp %u duty %u [%u]: ours %u stock %u\n",
                           k->wave, k->amp, k->duty, i, out[i], k->code[i]);
                bad++;
                break;
            }
        }
    }
    CHECK(bad == 0, "%u of %u cases differ from stock", bad,
          (unsigned)SIGGEN_STOCK_CASE_COUNT);
}

static void test_shape_properties(void)
{
    printf("[2] shape properties\n");
    uint16_t a[SIGGEN_CYCLE_SAMPLES], b[SIGGEN_CYCLE_SAMPLES];

    /* Sine table extraction cross-check, independent of the emulator:
     * table 0 is round(2047 + 2047 sin(2 pi i / 100)), scaled as stock. */
    siggen_wave_build(a, SIGGEN_SINE, 30, 50);
    unsigned off = 0;
    for (unsigned i = 0; i < SIGGEN_CYCLE_SAMPLES; i++) {
        long t = lround(2047.0 + 2047.0 * sin(2.0 * M_PI * i / 100.0));
        if (a[i] != 20 + t * 30 / 33) off++;
    }
    CHECK(off == 0, "sine cycle is not 20 + round(2047+2047 sin)*30/33 at %u samples", off);

    /* Clamps: amplitude above 3.0 V and duty above 100 % behave as the max. */
    for (unsigned w = 0; w < SIGGEN_WAVEFORM_COUNT; w++) {
        siggen_wave_build(a, (uint8_t)w, 30, 100);
        siggen_wave_build(b, (uint8_t)w, 255, 200);
        CHECK(memcmp(a, b, sizeof a) == 0, "wave %u: clamp of amp/duty", w);
    }

    /* Amplitude 0 is the +20 floor for every type (stock has no offset). */
    for (unsigned w = 0; w < SIGGEN_WAVEFORM_COUNT; w++) {
        siggen_wave_build(a, (uint8_t)w, 0, 50);
        unsigned n = 0;
        for (unsigned i = 0; i < SIGGEN_CYCLE_SAMPLES; i++) n += (a[i] != 20);
        CHECK(n == 0, "wave %u at amp 0 leaves the 20 floor at %u samples", w, n);
    }

    /* Half/Full sit on the 2047 pedestal: min ~ amp/2, not the floor. */
    siggen_wave_build(a, SIGGEN_HALF_WAVE, 30, 50);
    unsigned mn = 0xFFFF;
    for (unsigned i = 0; i < SIGGEN_CYCLE_SAMPLES; i++) if (a[i] < mn) mn = a[i];
    CHECK(mn == 20 + 2047 * 30 / 33, "half wave floor %u", mn);

    /* Duty applies to Square and Sawtooth only; the others ignore it. */
    for (unsigned w = 0; w < SIGGEN_WAVEFORM_COUNT; w++) {
        siggen_wave_build(a, (uint8_t)w, 30, 10);
        siggen_wave_build(b, (uint8_t)w, 30, 90);
        bool differs = memcmp(a, b, sizeof a) != 0;
        CHECK(differs == siggen_wave_uses_duty((uint8_t)w),
              "wave %u duty dependence %d", w, differs);
    }

    /* An out-of-range index builds a flat floor rather than reading past
     * the tables, and the name lookup does not index past its array. */
    siggen_wave_build(a, SIGGEN_WAVEFORM_COUNT, 30, 50);
    CHECK(a[0] == 20 && a[99] == 20, "unknown wave not flat 20");
    CHECK(strcmp(siggen_wave_name(SIGGEN_WAVEFORM_COUNT), "?") == 0, "name ?");
    CHECK(strcmp(siggen_wave_name(SIGGEN_LORENTZ), "Lorentz") == 0, "name 12");
}

static double timing_hz(const siggen_timing_t *t)
{
    return (double)TMR7_CLK /
           (100.0 * ((double)t->div + 1.0) * ((double)t->pr + 1.0));
}

static void test_timing(void)
{
    printf("[3] TMR7 DIV/PR\n");
    siggen_timing_t t, s;

    CHECK(!siggen_timing_compute(0, TMR7_CLK, &t), "f = 0 must be off");
    CHECK(!siggen_timing_compute(1000, 0, &t), "clk = 0 must refuse");

    /* The bench anchor: stock programs DIV 1199 / PR 1 for 1 kHz. */
    CHECK(siggen_timing_stock(1000, TMR7_CLK, &s) && s.div == 1199 && s.pr == 1,
          "stock 1 kHz: DIV %u PR %u", s.div, s.pr);
    CHECK(siggen_timing_compute(1000, TMR7_CLK, &t) && t.div == 0 && t.pr == 2399 &&
          t.actual_mhz == 1000000u, "ours 1 kHz: DIV %u PR %u %u mHz",
          t.div, t.pr, (unsigned)t.actual_mhz);

    /* Stock's 1 Hz overflows the 16-bit DIV (119999 -> 54463): ~2.2 Hz. */
    siggen_timing_stock(1, TMR7_CLK, &s);
    CHECK(s.div == 54463 && s.pr == 19 && s.actual_mhz > 2200 && s.actual_mhz < 2210,
          "stock 1 Hz: DIV %u PR %u %u mHz", s.div, s.pr, (unsigned)s.actual_mhz);
    siggen_timing_compute(1, TMR7_CLK, &t);
    CHECK(t.actual_mhz == 1000, "ours 1 Hz: %u mHz", (unsigned)t.actual_mhz);

    /* The top: N = 48, 49999 Hz lands on 50 kHz. */
    siggen_timing_compute(50000, TMR7_CLK, &t);
    CHECK(t.div == 0 && t.pr == 47 && t.actual_mhz == 50000000u,
          "50 kHz: DIV %u PR %u", t.div, t.pr);

    unsigned worse = 0, bad_pr = 0, bad_mhz = 0, far = 0;
    double worst = 0.0;
    for (uint32_t f = 1; f <= SIGGEN_FREQ_MAX_HZ; f++) {
        siggen_timing_compute(f, TMR7_CLK, &t);
        siggen_timing_stock(f, TMR7_CLK, &s);
        if (t.pr < 1) bad_pr++;
        double ours = timing_hz(&t), stock = timing_hz(&s);
        double eo = fabs(ours - f), es = fabs(stock - f);
        if (eo > es + 1e-9) worse++;
        /* Optimal for its DIV: the neighbouring periods are no nearer f
         * (a PR beyond 16 bits or below 1 is not a candidate). */
        siggen_timing_t nb = t;
        for (int d = -1; d <= 1; d += 2) {
            long pr = (long)t.pr + d;
            if (pr < 1 || pr > 65535) continue;
            nb.pr = (uint16_t)pr;
            if (fabs(timing_hz(&nb) - f) + 1e-9 < eo) far++;
        }
        if (eo / f > worst) worst = eo / f;
        if (fabs((double)t.actual_mhz - ours * 1000.0) > 0.5 + 1e-6) bad_mhz++;
    }
    printf("  worst relative error 1..50000 Hz: %.3g\n", worst);
    CHECK(bad_pr == 0, "%u frequencies programme PR = 0", bad_pr);
    CHECK(worse == 0, "%u frequencies less accurate than stock", worse);
    CHECK(far == 0, "%u frequencies where a neighbouring PR is nearer", far);
    CHECK(bad_mhz == 0, "%u actual_mhz values not rounded", bad_mhz);
}

static void test_dac_ctrl(void)
{
    printf("[4] DAC_CTRL keeps channel 1\n");
    /* Exact stock upper halves. */
    CHECK(siggen_dac_ctrl_ch2(0, SIGGEN_DAC_TSEL_TMR7, true) == 0x10150000u,
          "run word 0x%08X", (unsigned)siggen_dac_ctrl_ch2(0, 2, true));
    CHECK(siggen_dac_ctrl_ch2(0, SIGGEN_DAC_TSEL_TMR7, false) == 0x10140000u,
          "pre-enable word");
    CHECK(siggen_dac_ctrl_ch2(0, SIGGEN_DAC_TSEL_SW, true) == 0x103D0000u,
          "software-trigger word");

    /* The scope's CH1 word (0x3D: D1EN | D1TRGEN | D1TRGSEL = 7) survives,
     * and whatever channel 2 held before is replaced, not OR-ed. */
    CHECK(siggen_dac_ctrl_ch2(0xFFFF003Du, SIGGEN_DAC_TSEL_TMR7, true) == 0x1015003Du,
          "0x%08X", (unsigned)siggen_dac_ctrl_ch2(0xFFFF003Du, 2, true));

    uint32_t x = 0x12345678u;
    unsigned bad = 0;
    for (unsigned i = 0; i < 100000; i++) {
        x = x * 1664525u + 1013904223u;
        uint8_t tsel = (uint8_t)(i & 7u);
        bool en = (i >> 3) & 1u;
        uint32_t v = siggen_dac_ctrl_ch2(x, tsel, en);
        if ((v & 0xFFFFu) != (x & 0xFFFFu)) bad++;
        if (v & SIGGEN_DAC_D2OBDIS) bad++;                 /* buffer ON */
        if (((v >> 19) & 7u) != tsel) bad++;
        if (((v >> 16) & 1u) != (uint32_t)en) bad++;
        if ((v & 0xEFC00000u) != 0) bad++;           /* NM, NBSEL, 31:29 */
    }
    CHECK(bad == 0, "%u composed words broke channel 1 or the ch2 fields", bad);
}

int main(void)
{
    test_stock_cycles();
    test_shape_properties();
    test_timing();
    test_dac_ctrl();
    printf("\n%d checks, %d failed\n", checks, failures);
    return failures ? 1 : 0;
}
